draw:
function draw(ctx, t, W, H) {
  ctx.save();
  ctx.fillStyle = '#f5f0e8';
  ctx.fillRect(0, 0, W, H);

  // Draw Aristotle
  ctx.strokeStyle = 'black';
  ctx.lineWidth = 3;
  ctx.beginPath();
  ctx.arc(W/2, H/2, 20, 0, 2 * Math.PI);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2, H/2 + 20);
  ctx.lineTo(W/2, H/2 + 50);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2, H/2 + 50);
  ctx.lineTo(W/2 - 20, H/2 + 70);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2, H/2 + 50);
  ctx.lineTo(W/2 + 20, H/2 + 70);
  ctx.stroke();

  // Draw book
  ctx.beginPath();
  ctx.rect(W/2 - 30, H/2 - 50, 60, 20);
  ctx.stroke();

  // Draw virtue words
  ctx.font = '14px Arial';
  ctx.textAlign = 'center';
  ctx.textBaseline = 'middle';
  ctx.fillStyle = 'black';
  ctx.fillText('Virtue', W/2, H/2 - 70 + 20 * Math.sin(t));

  // Draw mean words
  ctx.fillText('Mean', W/2 - 40 + 20 * Math.cos(t), H/2 + 90);
  ctx.fillText('Excess', W/2 + 40 + 20 * Math.cos(t), H/2 + 90);

  ctx.restore();
}
